ceOpenAdd:
function ceOpenAdd(kid){
  if(ceCloseTimer){clearTimeout(ceCloseTimer);ceCloseTimer=null;}
  ceAddKid=kid;
  ceAddForm={name:"",device:"paper",mom:"none",minutes:25,days:"Mon Tue Wed Thu Fri",rules:"sequential",total:50,startAt:1,lessonSource:"auto",prefix:"Lesson",manualLessons:"",daysPerLesson:1,allowedDays:[],priority:"normal",carryoverCap:2,stickyWith:"",stickyOrder:"after",tracking:"sequenced",timesPerWeek:5,fixedTime:"",fixedDates:[],joinUrl:""};
  ceAddMsg="";
  ceRenderAddSheet();
}

ceRenderAddSheet:
function ceRenderAddSheet(){
  const w=document.getElementById("ce-sheet-wrap");
  const kid=ceAddKid;
  const f=ceAddForm;
  const col=KID_COLOR[kid]||"#333";

  let h='<div class="ce-sheet" onclick="if(event.target===this)ceCloseSheet()"><div class="ce-sheet-box">';
  h+='<div class="ce-sheet-title">Add Subject for '+cap(kid)+'</div>';
  if(typeof famWhoRowHTML==="function") h+=famWhoRowHTML(f);   // 🏡 FAMEDITORHOME: "Who does this?" — 2+ kids = one Family Time subject

  // Subject name
  h+='<div class="ce-sheet-lbl">Subject Name</div>';
  h+='<input class="ce-sheet-input" id="ce-add-name" value="'+esc(f.name)+'" placeholder="e.g. Piano Practice" onchange="ceAddForm.name=this.value">';

  // Device
  h+='<div class="ce-sheet-lbl">'+cw("device")+'</div>';
  h+='<div class="ce-chips">';
  ["paper","computer","ipad/phone","book","keyboard"].forEach(d=>{
    h+='<div class="ce-chip'+(f.device===d?" sel":"")+'" onclick="ceAddForm.device=\''+d+'\';ceRenderAddSheet()">'+(CURR_DEV_EMOJI[d]||"")+" "+(CURR_DEV_LABEL[d]||cap(d))+'</div>';
  });
  h+='</div>';

  // Mom
  h+='<div class="ce-sheet-lbl">'+cw("momReq")+'</div>';
  h+='<div class="ce-chips">';
  [["none",cw("momNone")],["maybe",cw("momMaybe")],["required",cw("momRequired")]].forEach(([v,lbl])=>{
    h+='<div class="ce-chip'+(f.mom===v?" sel":"")+'" onclick="ceAddForm.mom=\''+v+'\';ceRenderAddSheet()">'+lbl+'</div>';
  });
  h+='</div>';

  // Duration
  h+='<div class="ce-sheet-lbl">'+cw("duration")+' (minutes)</div>';
  h+='<div class="ce-stepper">';
  h+='<button onclick="ceAddStepMin(-5)">&minus;</button>';
  h+='<span id="ce-add-min-val">'+f.minutes+'</span>';
  h+='<button onclick="ceAddStepMin(5)">+</button>';
  h+='</div>';

  // Times per week
  h+='<div class="ce-sheet-lbl">'+cw("tpw")+'</div>';
  h+='<div class="ce-stepper">';
  h+='<button onclick="ceAddForm.timesPerWeek=Math.max(1,ceAddForm.timesPerWeek-1);ceRenderAddSheet()">&minus;</button>';
  h+='<span>'+f.timesPerWeek+'</span>';
  h+='<button onclick="ceAddForm.timesPerWeek=Math.min(7,ceAddForm.timesPerWeek+1);ceRenderAddSheet()">+</button>';
  h+='</div>';
  if(f.tracking!=="daily"&&f.total>0&&f.timesPerWeek>0){
    const wksNeeded=Math.ceil(f.total/f.timesPerWeek);
    h+='<div style="font-size:10px;color:var(--muted);margin-top:4px">'+f.total+' lessons ÷ '+f.timesPerWeek+'×/week = '+wksNeeded+' week'+(wksNeeded!==1?"s":"")+'</div>';
