  // Days chips
  h+='<div class="ce-sheet-lbl">'+cw("days")+'</div>';
  const addDays=(f.days||"").split(/[\s,]+/).map(x=>x.trim()).filter(Boolean);
  h+='<div class="ce-chips">';
  ["Mon","Tue","Wed","Thu","Fri","Sat"].forEach(d=>{
