    h+='<div style="flex:1;font-size:10px;color:var(--muted);padding-bottom:8px">Runs for <b>'+(parseInt(f.minutes,10)||0)+' min</b> on <b>'+esc((f.allowedDays&&f.allowedDays.length)?f.allowedDays.join(" "):(f.days||"any school day"))+'</b> \u2014 set those with '+cw("duration")+' and '+cw("days")+' above.</div>';
    h+='</div>';
    h+='<div class="ce-sheet-lbl" style="margin-top:10px">'+cw("meetDates")+' <span style="font-weight:400;text-transform:none;letter-spacing:0;color:var(--muted)">\u2014 optional</span></div>';
    h+='<textarea class="ce-sheet-input" rows="3" placeholder="2026-09-16&#10;2026-09-23&#10;2026-09-30" style="width:100%;box-sizing:border-box;font-family:ui-monospace,monospace;font-size:11px" onchange="ceAddSetClassDates(this.value)">'+esc(_afxD.join("\n"))+'</textarea>';
    if(_afxD.length){
      h+='<div style="font-size:10px;color:#0f766e;margin-top:3px"><b>'+_afxD.length+'</b> meeting'+(_afxD.length===1?"":"s")+': '+esc(_afxD[0])+' \u2192 '+esc(_afxD[_afxD.length-1])+'. No card lands on any other day.</div>';
    } else {
      h+='<div style="font-size:10px;color:#92400e;margin-top:3px">Empty = it meets <b>every</b> pinned day, including holiday weeks. Paste the real dates so it skips the weeks with no class.</div>';
    }
    if(ceAddMsg) h+='<div style="font-size:10px;color:var(--muted);margin-top:3px">'+esc(ceAddMsg)+'</div>';
    h+='<div class="ce-sheet-lbl" style="margin-top:10px">Join link <span style="font-weight:400;text-transform:none;letter-spacing:0;color:var(--muted)">\u2014 optional</span></div>';
    h+='<input class="ce-sheet-input" placeholder="https://\u2026" value="'+esc(f.joinUrl||"")+'" oninput="ceAddForm.joinUrl=this.value">';
    h+='<div style="font-size:10px;color:var(--muted);margin-top:3px">A class wants one lesson per meeting \u2014 '+(_afxD.length?('<b>'+_afxD.length+'</b>'):'as many as there are dates')+', set below.</div>';
  }

  // Tracking mode
  h+='<div class="ce-sheet-lbl">'+cw("tracking")+'</div>';
  h+='<div class="ce-chips">';
  h+='<div class="ce-chip'+(f.tracking==="sequenced"?" sel":"")+'" onclick="ceAddForm.tracking=\'sequenced\';ceRenderAddSheet()">'+cw("seqd")+'</div>';
  h+='<div class="ce-chip'+(f.tracking==="daily"?" sel":"")+'" onclick="ceAddForm.tracking=\'daily\';ceRenderAddSheet()">'+cw("daily")+'</div>';
  h+='</div>';
  h+='<div style="font-size:10px;color:var(--muted);margin-top:4px">'+(f.tracking==="daily"?"Shows up each scheduled day without tracking lesson numbers":"Lessons advance in order and track progress with a cursor")+'</div>';

  // 📚 Study session link (memory curriculum): the card opens this study sitting and shows today's pile.
  {
    const _ss=(typeof mstSessions==="function")?mstSessions(ceAddKid):[];
