    h+='<div style="display:flex;align-items:center;gap:10px">';
    h+='<div class="ce-stepper">';
    h+='<button onclick="ceAddForm.total=Math.max(1,ceAddForm.total-10);ceRenderAddSheet()">&minus;10</button>';
    h+='<input type="number" class="ce-stepnum" min="1" max="500" value="'+f.total+'" onchange="ceAddSetTotal(this.value)">';
    h+='<button onclick="ceAddForm.total=Math.min(500,ceAddForm.total+10);ceRenderAddSheet()">+10</button>';
    h+='</div>';
    h+='<span style="font-size:11px;color:var(--muted)">start at</span><input type="number" class="ce-stepnum" min="1" max="500" value="'+(f.startAt||1)+'" title="The first lesson this kid will see \u2014 earlier ones are simply not in the list, so nothing has to be checked off to get there" onchange="ceAddForm.startAt=Math.max(1,parseInt(this.value,10)||1);ceRenderAddSheet()">';
    h+='<span style="font-size:11px;color:var(--muted)">'+f.prefix+' '+(f.startAt||1)+' &rarr; '+f.prefix+' '+f.total+'</span>';
    h+='</div>';
  } else {
    h+='<div class="ce-sheet-lbl">Lessons (one per line)</div>';
    h+='<textarea id="ce-add-lessons" class="ce-sheet-input" style="min-height:100px;resize:vertical;font-size:12px;line-height:1.6" placeholder="pg 1-3&#10;pg 4-6&#10;pg 7-9&#10;Chapter 2 Review&#10;..."'
      +' onchange="ceAddForm.manualLessons=this.value" oninput="ceAddForm.manualLessons=this.value">'+esc(f.manualLessons||"")+'</textarea>';
    h+='<div style="font-size:10px;color:var(--muted);margin-top:4px">Each line becomes one lesson. The generator assigns them in order.</div>';
  }
  { const _dpl=Math.max(1,parseInt(f.daysPerLesson,10)||1);
    h+='<div class="ce-sheet-lbl">Days per lesson</div>';
    h+='<div class="ce-stepper">';
    h+='<button onclick="ceAddForm.daysPerLesson=Math.max(1,(parseInt(ceAddForm.daysPerLesson,10)||1)-1);ceRenderAddSheet()">&minus;</button>';
    h+='<span>'+_dpl+'</span>';
    h+='<button onclick="ceAddForm.daysPerLesson=Math.min(10,(parseInt(ceAddForm.daysPerLesson,10)||1)+1);ceRenderAddSheet()">+</button>';
    h+='</div>';
    const _nL=f.lessonSource==="auto"?Math.max(0,(parseInt(f.total,10)||0)-Math.max(1,parseInt(f.startAt,10)||1)+1):String(f.manualLessons||"").split("\n").map(x=>x.trim()).filter(Boolean).length;
    h+='<div style="font-size:10px;color:var(--muted);margin-top:4px">'+(_dpl>1?('Each lesson takes '+_dpl+' days — one a day ("· day 1 of '+_dpl+'" …): '+_nL+' lessons → <b>'+(_nL*_dpl)+' days of work</b>. Set '+cw("tpw")+' to match.'):'1 = each lesson is done in one day.')+'</div>'; }

  // Priority
  h+='<div class="ce-sheet-lbl">'+cw("priority")+'</div>';
  h+='<div class="ce-chips">';
  ["low","normal","high"].forEach(p=>{
    h+='<div class="ce-chip'+(f.priority===p?" sel":"")+'" onclick="ceAddForm.priority=\''+p+'\';ceRenderAddSheet()">'+cw({low:"prLow",normal:"prNormal",high:"prHigh"}[p])+'</div>';
  });
  h+='</div>';

  // Carryover cap
  h+='<div class="ce-sheet-lbl">'+cw("carryCap")+'</div>';
  h+='<div class="ce-stepper">';
  h+='<button onclick="ceAddForm.carryoverCap=Math.max(0,ceAddForm.carryoverCap-1);ceRenderAddSheet()">&minus;</button>';
  h+='<span>'+f.carryoverCap+'</span>';
  h+='<button onclick="ceAddForm.carryoverCap=Math.min(5,ceAddForm.carryoverCap+1);ceRenderAddSheet()">+</button>';
  h+='</div>';
  } // end sequenced-only block

  // Actions
  h+='<div class="ce-sheet-actions">';
  h+='<button class="ce-btn-cancel" onclick="ceCloseSheet()">Cancel</button>';
  h+='<button class="ce-btn-save" onclick="ceAddSave()">Add Subject</button>';
  h+='</div>';

  h+='</div></div>';
  // Re-render in place when the sheet is already open: render it already-"open" (so the
  // entrance slide/fade doesn't replay) and restore scroll — otherwise each option click
  // blips the whole sheet. Only the first open plays the animation.
  const _wasOpen=!!w.querySelector(".ce-sheet.open");
  const _prevBox=w.querySelector(".ce-sheet-box");
  const _prevScroll=_prevBox?_prevBox.scrollTop:0;
  w.innerHTML=_wasOpen?h.replace('class="ce-sheet"','class="ce-sheet open"'):h;
  w.style.display="block";
  document.body.style.overflow="hidden";
  if(_wasOpen){
    const _nb=w.querySelector(".ce-sheet-box"); if(_nb) _nb.scrollTop=_prevScroll;
  } else {
    requestAnimationFrame(()=>{
      const sheet=w.querySelector(".ce-sheet");
      if(sheet) sheet.classList.add("open");
    });
  }
}

ceAddSave:
function ceAddSave(){
  if(typeof famWhoSave==="function"&&famWhoSave()) return;   // 🏡 FAMEDITORHOME: 2+ kids → one Family Time subject, no per-kid subject
  const nameEl=document.getElementById("ce-add-name");
  if(nameEl) ceAddForm.name=nameEl.value;
  const name=ceAddForm.name.trim();
  if(!name){ alert("Enter a subject name."); return; }
  if(!currData||!db) return;
  const kid=ceAddKid;
  if(!currData.subjects[kid]) currData.subjects[kid]={};
  const key=name.toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,"");
  if(currData.subjects[kid][key]){ alert("A subject with key \""+key+"\" already exists."); return; }
  const f=ceAddForm;
  const dayArr=(f.days||"").split(/[\s,]+/).map(x=>x.trim()).filter(Boolean);
  let subj;
  if(f.tracking==="daily"){
    subj={display:name,device:f.device,mom:f.mom,minutes:f.minutes,days:f.days,allowedDays:dayArr,rules:f.rules,tracking:"daily",priority:f.priority||"normal",timesPerWeek:f.timesPerWeek||5}; if(f.study){ subj.study=f.study; subj.noCarry=true; }
  } else {
    // Build lesson sequence
    let lessonSeq=[];
    if(f.lessonSource==="auto"){
      for(let i=Math.max(1,parseInt(f.startAt,10)||1);i<=f.total;i++) lessonSeq.push(f.prefix+" "+i);   // 🔢 Start at: earlier lessons are simply not in the list — no fake check-offs (2026-10-01)
    } else {
      const ta=document.getElementById("ce-add-lessons");
      if(ta) f.manualLessons=ta.value;
      lessonSeq=(f.manualLessons||"").split("\n").map(l=>l.trim()).filter(Boolean);
    }
    if((parseInt(f.daysPerLesson,10)||1)>1) lessonSeq=lessonExpandDays(lessonSeq,f.daysPerLesson);
    if(!lessonSeq.length){ alert("Add at least one lesson."); return; }
    // EGGQUIZ: a brand-new list has nothing finished — every "+ Quiz" line becomes lesson, then quiz.
    if(typeof eqSplit==="function"&&eqIsEggs(ceAddKid,null,{display:name})) lessonSeq=eqSplit(lessonSeq,null,null,1).seq;
    subj={display:name,device:f.device,mom:f.mom,minutes:f.minutes,days:f.days,allowedDays:dayArr,rules:f.rules,total:lessonSeq.length,priority:f.priority,carryoverCap:f.carryoverCap,lessonSeq:lessonSeq,timesPerWeek:f.timesPerWeek||5};
    { const _r=_lidAlign(null,null,lessonSeq,1,null,true); subj.lessonIds=_r.ids; subj.nextLid=_r.nextLid; }   // born with ids — no other device can hold a competing set
    // ADDPB (demo run F2, 2026-11-09): born PLAN-BACKED — it has ids and no history for "done by id" to disagree with, so its Build
    // re-lays this week through the one door (not "isn't paced by the Builder" until Sunday) and the week turn never deals its
    // never-dealt cells twice as "behind" (the legacy catch-up doubling is off for plan-backed subjects)
    subj.planId=(typeof planIdFor==="function")?planIdFor(kid,key):kid+"__"+key; subj.doneImportedAt=new Date().toISOString();
  }
  if(f.stickyWith){ subj.stickyWith=f.stickyWith; subj.stickyOrder=f.stickyOrder||"after"; }
  // A class set up on the Add sheet carries its clock time through to the saved subject.
  // Both tracking branches build `subj` above, so this rides after them — otherwise the
  // fields she just typed are silently dropped on save.
  if(f.fixedTime&&String(f.fixedTime).trim()){
    subj.fixedTime=f.fixedTime;
    if(Array.isArray(f.fixedDates)&&f.fixedDates.length) subj.fixedDates=f.fixedDates.slice();
    const _ju=(typeof fxSafeUrl==="function")?fxSafeUrl(f.joinUrl):String(f.joinUrl||"").trim();
    if(_ju) subj.joinUrl=_ju;
  }
  currData.subjects[kid][key]=subj;
  db.ref("curriculum/subjects/"+kid+"/"+key).set(subj);
  currData.lastEdit=new Date().toISOString();
  db.ref("curriculum/lastEdit").set(currData.lastEdit);
  // 🔁 RELAY4 (2026-11-08): a new DAILY lays into the rest of this week now, through the one door (Undo = the subject and its cards
  // gone again); a new sequenced subject is born plan-backed (ADDPB) — it lays here by its days, and again when she Builds it below
  // (cbApply → the same door)
  try{ if(typeof _rlwCurrDoor==="function") _rlwCurrDoor("📚 "+(subj.display||key)+" added",[{kid:kid,sk:key}],[{p:"curriculum/subjects/"+kid+"/"+key,gone:true}],{toast:false}); }catch(e){}
  ceCloseSheet();
  // A new SEQUENCED subject flows straight into pacing: its card sheet reopens
  // with 🧱 already expanded — set the mode, Preview, Build, done. (Dailies
  // schedule on their own; nothing to pace.)
  if(subj.tracking!=="daily"){
    ceBuildOpen=kid+"|"+key;
    cbKid=kid; cbSubjKey=key; cbForm=cbDefaultForm(kid,key); cbPreviewRes=null;
    ceOpenEdit(kid,key);
    if(typeof gwShowToast==="function") gwShowToast("📚 "+(subj.display||key)+" added — now pace and build it below.");
  }
  renderAll();
}
